import { Children, ReactNode } from 'react';
import { isElement } from 'react-is';

import { SparklineRendererProps } from '../../sparkline/components/SparklineRenderer.js';
import { defaultYAxisConfig } from '../../sparkline/constants.js';
import {
  Threshold,
  SparklineThresholdProps,
} from '../../sparkline/slots/Threshold.js';
import { SparklineYAxisProps, YAxis } from '../../sparkline/slots/YAxis.js';
import { TrendProps } from '../components/trend/types/trend-props.js';
import { Sparkline } from '../slots/Sparkline.js';
import { Trend } from '../slots/Trend.js';

export interface SingleValueSlots {
  sparkline?: SparklineRendererProps;
  trend?: TrendProps;
}

const iterateSparklineSlots = (children: ReactNode) => {
  const thresholds: SparklineThresholdProps[] = [];
  let yAxis: SparklineYAxisProps = defaultYAxisConfig;
  Children.forEach(children, (sparklineChild) => {
    if (isElement(sparklineChild)) {
      switch (sparklineChild.type) {
        case Threshold: {
          thresholds.push(sparklineChild.props);
          break;
        }
        case YAxis: {
          yAxis = {
            ...yAxis,
            ...(sparklineChild.props as SparklineYAxisProps),
          };
          break;
        }
      }
    }
  });

  return { thresholds, yAxis };
};

export const iterateSlots = (
  children: ReactNode,
): { slots: SingleValueSlots; sparklineChildren: ReactNode } => {
  const slots: SingleValueSlots = {};
  let sparklineChildren: ReactNode;

  Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Sparkline: {
          const { children: sparklineSlots, ...props } = child.props;
          const { thresholds, yAxis } = iterateSparklineSlots(sparklineSlots);

          slots.sparkline = {
            ...props,
            ...(thresholds.length > 0 ? { thresholds } : {}),
            yAxis,
          };
          sparklineChildren = sparklineSlots;
          break;
        }
        case Trend: {
          const { children, ...props } = child.props;

          slots.trend = {
            ...props,
          };

          break;
        }
      }
    }
  });

  return { slots, sparklineChildren };
};
